    public Object calculate(String formula, Map<String, Object> context) throws ScriptException {
        if (formula == null || formula.trim().isEmpty()) {
            throw new IllegalArgumentException("Formula must not be null or empty");
        }
        if (context == null) {
            throw new IllegalArgumentException("Context must not be null");
        }

        // Create bindings from the context map
        SimpleBindings bindings = new SimpleBindings();
        bindings.putAll(context);

        // Evaluate the formula with the bindings
        try {
            return engine.eval(formula, bindings);
        } catch (ScriptException e) {
            // Re-throw with a more descriptive message if needed
            throw new ScriptException("Error evaluating formula: " + formula + " - " + e.getMessage());
        }
    }
}
